/* Batch timeline actions use one undo checkpoint and preserve relative timing. */
function selectionClips(){const ids=new Set(getSelectionIds());return project.clips.filter(c=>ids.has(c.id));}
function editableSelection(){const clips=selectionClips();if(exporting||!clips.length)return null;if(clips.some(clipLocked)){toast('Unlock all selected tracks to edit these clips.');return null;}return clips;}
function batchChange(change){const clips=editableSelection();if(!clips)return;stop();checkpoint();change(clips);commit();}
const singleDelete=deleteClip,singleDuplicate=duplicateClip,singleSplit=splitClip;
deleteClip=function(){if(getSelectionIds().length<2)return singleDelete();batchChange(clips=>{const ids=new Set(clips.map(c=>c.id));project.clips=project.clips.filter(c=>!ids.has(c.id));setSelection([]);});};
duplicateClip=function(){if(getSelectionIds().length<2)return singleDuplicate();batchChange(clips=>{
 const left=Math.min(...clips.map(c=>c.start)),right=Math.max(...clips.map(c=>c.start+c.duration));let layer=Math.max(0,...project.clips.map(c=>c.layer||0));
 const copies=clips.map(c=>{const copy={...Model.clone(c),id:uid(),start:c.start+right-left};if(copy.track==='overlay')copy.layer=++layer;return copy;});project.clips.push(...copies);setSelection(copies.map(c=>c.id));
});};
splitClip=function(){if(getSelectionIds().length<2)return singleSplit();const clips=editableSelection();if(!clips)return;const cuts=clips.map(c=>({c,pieces:Model.split(c,playhead)})).filter(x=>x.pieces);if(!cuts.length)return toast('Place the playhead inside a selected clip.');stop();checkpoint();const ids=[];for(const {c,pieces} of cuts){Object.assign(c,pieces[0]);const right={...pieces[1],id:uid()};project.clips.push(right);ids.push(c.id,right.id);}setSelection([...new Set([...getSelectionIds(),...ids])]);commit();};
$('#delete').onclick=deleteClip;$('#duplicate').onclick=duplicateClip;$('#split').onclick=splitClip;
const singleDetachAudio=detachAudio;
detachAudio=function(){if(getSelectionIds().length>1)return toast('Select one video clip to detach its audio.');return singleDetachAudio();};
$('#detach-audio').onclick=detachAudio;
const beforeMultiTimeline=renderTimeline;
renderTimeline=function(){beforeMultiTimeline();const count=getSelectionIds().length;if(count>1)$('#selection-info').textContent=`${count} pieces selected · Shift-click to change selection`;};
const beforeMultiControls=updateControls;
updateControls=function(){beforeMultiControls();const clips=selectionClips();if(clips.length>1){const blocked=exporting||clips.some(clipLocked);for(const id of ['split','duplicate','delete'])$('#'+id).disabled=blocked;for(const id of ['ripple-delete','detach-audio'])$('#'+id).disabled=true;$('#selection-info').textContent=`${clips.length} pieces selected · Shift-click to change selection`;}};
const beforeMultiInspector=renderInspector;
renderInspector=function(){const clips=selectionClips();if(clips.length<2)return beforeMultiInspector();
 const root=$('#inspector-content'),locked=clips.some(clipLocked),textOnly=clips.every(c=>c.track==='text'),soundOnly=clips.every(c=>c.track==='audio');$('#inspector-tab').textContent='Selection';root.classList.remove('audio-workspace');
 root.innerHTML=`<div class="inspector-section multi-hero"><h3>${clips.length} pieces selected</h3><p class="small-help">Drag a selected piece to move the group. Shift-click toggles pieces. Drag a box on empty timeline space to select an area.</p><div class="batch-actions"><button id="batch-split" class="secondary">Split at playhead</button><button id="batch-duplicate" class="secondary">Duplicate</button><button id="batch-delete" class="secondary">Delete selected</button><button id="batch-clear" class="secondary">Clear selection</button></div>${locked?'<p class="small-help">Unlock selected tracks to edit this group.</p>':''}</div><div class="inspector-section"><h3>Move together</h3><label class="field">Offset · seconds<input id="batch-offset" type="number" step=".1" value="0"></label><button id="batch-move" class="secondary wide">Apply offset</button></div>${textOnly?'<div class="inspector-section"><h3>Caption & text style</h3><label class="field">Font size<input id="batch-font" type="number" min="16" max="200" value="'+clips[0].fontSize+'"></label><label class="field">Text color<input id="batch-color" type="color" value="'+esc(clips[0].color||'#ffffff')+'"></label><button id="batch-text" class="secondary wide">Apply style to selected text</button></div>':''}${soundOnly?'<div class="inspector-section"><h3>Audio volume</h3><label class="field">Volume %<input id="batch-volume" type="number" min="0" max="100" value="'+clips[0].volume+'"></label><button id="batch-volume-apply" class="secondary wide">Apply volume to selected audio</button><button id="batch-mute" class="secondary wide">'+(clips.every(c=>c.audioMuted)?'Unmute selected audio':'Mute selected audio')+'</button></div>':''}`;
 $('#batch-clear').onclick=()=>{setSelection([]);commit();};$('#batch-delete').onclick=deleteClip;$('#batch-duplicate').onclick=duplicateClip;$('#batch-split').onclick=splitClip;
 $('#batch-move').onclick=()=>{const input=$('#batch-offset'),n=Number(input.value);if(input.value===''||!Number.isFinite(n))return;batchChange(list=>{const offset=Math.max(n,-Math.min(...list.map(c=>c.start)));list.forEach(c=>c.start+=offset);});};
 if(textOnly)$('#batch-text').onclick=()=>{const input=$('#batch-font');if(input.value===''||!input.checkValidity())return toast('Choose a font size from 16 to 200.');const size=Number(input.value),color=$('#batch-color').value;batchChange(list=>list.forEach(c=>{c.fontSize=size;c.color=color;}));};
 if(soundOnly){$('#batch-volume-apply').onclick=()=>{const input=$('#batch-volume');if(input.value===''||!input.checkValidity())return;const value=Number(input.value);batchChange(list=>list.forEach(c=>c.volume=value));};$('#batch-mute').onclick=()=>{const value=!clips.every(c=>c.audioMuted);batchChange(list=>list.forEach(c=>c.audioMuted=value));};}
 if(locked||exporting)$$('button,input',root).forEach(el=>{if(el.id!=='batch-clear')el.disabled=true;});
};
// Capture shortcuts before the existing single-clip clipboard handlers.
let multiClipboard=null;
window.addEventListener('keydown',e=>{
 if(e.target.matches('input,textarea,select')||$('dialog[open]')||exporting)return;
 const command=e.metaKey||e.ctrlKey,count=getSelectionIds().length;
 if(command&&e.code==='KeyA'&&e.target.closest('.timeline')){e.preventDefault();e.stopImmediatePropagation();setSelection(project.clips.filter(c=>!clipLocked(c)).map(c=>c.id));renderTimeline();renderInspector();updateControls();}
 if(e.code==='Escape'&&count>1){setSelection([]);renderTimeline();renderInspector();updateControls();}
 if(command&&e.code==='KeyC'){if(count>1){e.preventDefault();e.stopImmediatePropagation();multiClipboard=Model.clone(selectionClips());toast(`${count} pieces copied.`);}else multiClipboard=null;}
 if(command&&e.code==='KeyV'&&multiClipboard){e.preventDefault();e.stopImmediatePropagation();if(multiClipboard.some(c=>project.locked[c.track]))return toast('Unlock the destination tracks first.');stop();checkpoint();const left=Math.min(...multiClipboard.map(c=>c.start));let layer=Math.max(0,...project.clips.map(c=>c.layer||0));const copies=multiClipboard.map(c=>{const copy={...Model.clone(c),id:uid(),start:playhead+c.start-left};if(copy.track==='overlay')copy.layer=++layer;return copy;});project.clips.push(...copies);setSelection(copies.map(c=>c.id));commit();}
},true);
// Right-click inside a group keeps its selection and opens group actions.
$('#track-area').addEventListener('contextmenu',e=>{const el=e.target.closest('[data-clip]');if(getSelectionIds().length<2||!el||!getSelectionIds().includes(el.dataset.clip))return;e.preventDefault();e.stopImmediatePropagation();closeContextMenu();const menu=document.createElement('div');menu.id='clip-menu';menu.className='clip-menu';menu.innerHTML='<button data-batch="split">Split selected at playhead</button><button data-batch="duplicate">Duplicate selection</button><button data-batch="delete">Delete selection</button>';document.body.append(menu);menu.style.left=Math.max(0,Math.min(e.clientX,innerWidth-225))+'px';menu.style.top=Math.max(0,Math.min(e.clientY,innerHeight-menu.offsetHeight-12))+'px';menu.onclick=e=>{const action=e.target.closest('[data-batch]')?.dataset.batch;closeContextMenu();({split:splitClip,duplicate:duplicateClip,delete:deleteClip})[action]?.();};},true);
